css:
.ortsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a2440;
    background: linear-gradient(165deg, #fbf6ec 0%, #f4ece0 48%, #efe6f0 100%);
    border-radius: 18px;
}

.ortsim-container * {
    box-sizing: border-box;
}

.ortsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #3a2d6d 0%, #5b3aa0 52%, #b5582a 100%);
    color: #fdf6ec;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #4b3a86;
    box-shadow: 0 12px 32px rgba(58, 45, 109, 0.30);
}

.ortsim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #fff6e9;
}

.ortsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffd9a8;
    background: rgba(255, 217, 168, 0.14);
    border: 1px solid rgba(255, 217, 168, 0.38);
    padding: 5px 14px;
    border-radius: 999px;
}

.ortsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #ece2f3;
}

.ortsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #5a5076;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.ortsim-period-counter #currentDay,
.ortsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #b5582a;
}

.ortsim-round-name {
    background: rgba(91, 58, 160, 0.12);
    color: #5b3aa0;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.ortsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a8452a;
    background: rgba(181, 88, 42, 0.12);
    border: 1px solid rgba(181, 88, 42, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.ortsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.ortsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e7ddcd;
    box-shadow: 0 6px 16px rgba(58, 45, 109, 0.08);
    border-top: 4px solid #5b3aa0;
}

.ortsim-card-comm { border-top-color: #b5582a; }
.ortsim-card-identity { border-top-color: #5b3aa0; }
.ortsim-card-trust { border-top-color: #2f8f6b; }
.ortsim-card-revenue { border-top-color: #c79a1e; }

.ortsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7f99;
}

.ortsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2a2440;
    font-variant-numeric: tabular-nums;
}

.ortsim-card-comm .ortsim-value { color: #b5582a; }
.ortsim-card-identity .ortsim-value { color: #5b3aa0; }
.ortsim-card-trust .ortsim-value { color: #2f8f6b; }
.ortsim-card-revenue .ortsim-value { color: #b88a12; }

.ortsim-sublabel {
    font-size: 0.75rem;
    color: #948aa3;
    line-height: 1.35;
}

.ortsim-comm-strong { border-top-color: #2f8f6b; }
.ortsim-comm-strong .ortsim-value { color: #2f8f6b; }
.ortsim-comm-weak { border-top-color: #c0392b; }
.ortsim-comm-weak .ortsim-value { color: #c0392b; }

.ortsim-trust-low { border-top-color: #c0392b; }
.ortsim-trust-low .ortsim-value { color: #c0392b; }
.ortsim-trust-high { border-top-color: #2f8f6b; }
.ortsim-trust-high .ortsim-value { color: #2f8f6b; }

.ortsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e7ddcd;
    color: #4a4163;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    box-shadow: 0 4px 12px rgba(58, 45, 109, 0.06);
}

.ortsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #b5582a;
}

.ortsim-budget-over #budgetDisplay {
    color: #c0392b;
}

.ortsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #b5582a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(58, 45, 109, 0.08);
}

.ortsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.ortsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #3a2d6d;
    margin-bottom: 6px;
}

.ortsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a4163;
}

.ortsim-briefing-text strong { color: #b5582a; }
.ortsim-briefing-text em { color: #5b3aa0; font-style: italic; }

.ortsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e7ddcd;
    box-shadow: 0 6px 16px rgba(58, 45, 109, 0.08);
}

.ortsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #3a2d6d;
    border-bottom: 2px solid #f0e7d8;
    padding-bottom: 8px;
}

.ortsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #43395f;
    margin: 14px 0 6px;
}

.ortsim-container select,
.ortsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d8ccb8;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf8;
    color: #2a2440;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.ortsim-container select:focus,
.ortsim-container input[type="number"]:focus {
    outline: none;
    border-color: #5b3aa0;
    box-shadow: 0 0 0 3px rgba(91, 58, 160, 0.15);
}

.ortsim-container select option {
    background-color: #fffdf8;
    color: #2a2440;
}

.ortsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b5582a;
}

.ortsim-range-readout,
.ortsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5a5076;
    margin-top: 4px;
}

.ortsim-range-readout span:last-child,
.ortsim-alloc-readout span:nth-child(2) {
    color: #b5582a;
    font-weight: 800;
}

.ortsim-hint {
    font-size: 0.8rem;
    color: #948aa3;
    margin-top: 4px;
    line-height: 1.4;
}

.ortsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.ortsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #faf5ec;
    border: 1px solid #ecdfc9;
    border-radius: 9px;
    padding: 8px 12px;
}

.ortsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #43395f;
}

.ortsim-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.ortsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.ortsim-container .btn-primary {
    background: linear-gradient(135deg, #5b3aa0 0%, #b5582a 100%);
    border: none;
    color: #fff6e9;
    padding: 11px 28px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(91, 58, 160, 0.30);
}

.ortsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.ortsim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #d8ccb8;
    color: #5a5076;
    background: transparent;
}

.ortsim-coach {
    background: linear-gradient(160deg, #2f2553 0%, #43306e 100%);
    color: #ece2f3;
    border: 1px solid #4b3a86;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(47, 37, 83, 0.25);
}

.ortsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffd9a8;
    margin-bottom: 8px;
}

.ortsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.ortsim-coach-body strong { color: #ffd9a8; }
.ortsim-coach-body em { color: #c9b3ff; font-style: italic; }

.ortsim-history,
.ortsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e7ddcd;
    box-shadow: 0 6px 16px rgba(58, 45, 109, 0.08);
}

.ortsim-history h3,
.ortsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #3a2d6d;
}

.ortsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #43395f;
}

.ortsim-container table#usfHistoryTable th {
    background: #f5edde;
    color: #5b3aa0;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e7d9bf;
}

.ortsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0e7d8;
    color: #4a4163;
}

.ortsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fbf6ec;
}

.ortsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .ortsim-container {
        padding: 14px;
    }
    .ortsim-header h1 {
        font-size: 1.7rem;
    }
    .ortsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .ortsim-value {
        font-size: 2rem;
    }
    .ortsim-clock {
        margin-left: 0;
    }
    .ortsim-period-counter {
        font-size: 0.88rem;
    }
    .ortsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .ortsim-alloc-row {
        flex-wrap: wrap;
    }
    .ortsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .ortsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}



/* \u2500\u2500 v1.1.0 completion scorecard (append-only, namespaced .ort-cm-*, academic maroon/plum/gold) \u2500\u2500 */
.ort-cm { margin-top: 8px; }
.ort-cm-incomplete { text-align: center; color: #5a4b52; font-size: 1rem; padding: 18px; }
.ort-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.ort-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #5c2233 0%, #8a3d5c 55%, #c9a227 135%); color: #ffffff; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(92, 34, 51, 0.28); }
.ort-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.ort-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.ort-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #f0dca0; }
.ort-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #ffffff; border: 1px solid #e6dbdf; border-left: 5px solid #8a3d5c; border-radius: 14px; padding: 16px 20px; }
.ort-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #6b5b62; }
.ort-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #5c2233; line-height: 1.15; }
.ort-cm-section { margin-bottom: 16px; }
.ort-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #6b5b62; margin-bottom: 8px; }
.ort-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.ort-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.ort-cm-ok { background: rgba(31, 157, 85, 0.14); color: #1f9d55; border-color: rgba(31, 157, 85, 0.42); }
.ort-cm-no { background: rgba(214, 69, 69, 0.12); color: #d64545; border-color: rgba(214, 69, 69, 0.42); }
.ort-cm-ico { font-weight: 800; }
.ort-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; }
.ort-cm-kpi { background: #ffffff; border: 1px solid #e6dbdf; border-top: 4px solid #c9a227; border-radius: 12px; padding: 14px 12px; text-align: center; }
.ort-cm-kpi-val { font-size: 1.6rem; font-weight: 800; color: #5c2233; line-height: 1; }
.ort-cm-kpi-lbl { margin-top: 6px; font-size: 0.82rem; font-weight: 700; color: #33262b; }
.ort-cm-kpi-sub { margin-top: 2px; font-size: 0.7rem; color: #6b5b62; }
.ort-cm-insights { margin: 0; padding-left: 18px; color: #33262b; }
.ort-cm-insights li { margin: 4px 0; font-size: 0.92rem; line-height: 1.45; }
@media (max-width: 560px) { .ort-cm-head { flex-direction: column; } .ort-cm-score { min-width: 0; } }

