(function() {
    'use strict';

    class OrtAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Identity at the Crossroads`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Pragati ORT).
            this.BUDGET = 9.0;            // ₹9 crore flat budget (hard constraint)
            this.COMBINED_NEED = 16.0;    // ₹16 crore combined need across four inventions
            this.DEEPTECH_NEED = 7.0;     // ₹7 crore, 4–5 yr horizon, best identity fit
            this.SOFTWARE_NEED = 1.5;     // ₹1.5 crore, revenue in 6 months
            this.DEVICE_OFFER = 5.0;      // ₹5 crore strategic-investor offer (exclusive + board seat)
            this.ANCHOR_ROYALTY = 2.2;    // ~₹2.2 crore/year anchor running royalty (at risk)
            this.COMM_BASELINE = 100;     // commercialization index baseline (18 invs ≈ 7.5%)
            this.COMM_TARGET = 300;       // Dean's 3x mandate

            // Concept truths.
            this.TRUE_STANCE = `reconcile`;
            this.TRUE_PRIORITY = `balanced`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    comm: 100,               // commercialization index (baseline 100, target ~300)
                    identity: 50,            // reconciled academic+commercial identity coherence
                    trust: 55,               // faculty disclosure & cooperation goodwill
                    revenue: 2.2,            // projected running royalty ₹ crore/yr (anchor base)
                    budgetUsed: 0,           // ₹ crore committed across the portfolio
                    cededControl: false,
                    inventorLost: false,
                    overCommitted: false,
                    commHistory: [100],
                    identityHistory: [50],
                    trustHistory: [55],
                    revenueHistory: [2.2],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a click-through must not auto-win.
                state.decisions = {
                    stance: `reporting`,
                    priority: `software`,
                    inventor: 40,
                    deviceModel: `exclusive`,
                    deeptechModel: `pass`,
                    softwareModel: `exclusive`,
                    deeptechSpend: 2.5,
                    deviceSpend: 2.0,
                    softwareSpend: 2.0,
                    pipelineSpend: 2.5,
                    anchor: `concede`,
                    identityStance: `commercial`,
                    inventorRes: `pressure`,
                    ramp: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const st = document.getElementById(`stanceInput`);
                const pr = document.getElementById(`priorityInput`);
                const iv = document.getElementById(`inventorInput`);
                if (st) decisions.stance = st.value;
                if (pr) decisions.priority = pr.value;
                if (iv) decisions.inventor = parseInt(iv.value, 10);
                if (!Number.isFinite(decisions.inventor) || decisions.inventor < 0 || decisions.inventor > 100) {
                    warn(`warn_inventor_range`); return false;
                }
            } else if (round === 2) {
                const dv = document.getElementById(`deviceModelInput`);
                const dt = document.getElementById(`deeptechModelInput`);
                const sw = document.getElementById(`softwareModelInput`);
                if (dv) decisions.deviceModel = dv.value;
                if (dt) decisions.deeptechModel = dt.value;
                if (sw) decisions.softwareModel = sw.value;
                if (!decisions.deviceModel || !decisions.deeptechModel || !decisions.softwareModel) {
                    warn(`warn_model_missing`); return false;
                }
            } else if (round === 3) {
                const dt = document.getElementById(`deeptechSpend`);
                const dv = document.getElementById(`deviceSpend`);
                const sw = document.getElementById(`softwareSpend`);
                const pl = document.getElementById(`pipelineSpend`);
                const an = document.getElementById(`anchorInput`);
                if (dt) decisions.deeptechSpend = parseFloat(dt.value);
                if (dv) decisions.deviceSpend = parseFloat(dv.value);
                if (sw) decisions.softwareSpend = parseFloat(sw.value);
                if (pl) decisions.pipelineSpend = parseFloat(pl.value);
                if (an) decisions.anchor = an.value;
                const parts = [decisions.deeptechSpend, decisions.deviceSpend, decisions.softwareSpend, decisions.pipelineSpend];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((parts[0] + parts[1] + parts[2] + parts[3]) * 10) / 10;
                if (Math.abs(total - this.BUDGET) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 4) {
                const id = document.getElementById(`identityStanceInput`);
                const ir = document.getElementById(`inventorResInput`);
                const rp = document.getElementById(`rampInput`);
                if (id) decisions.identityStance = id.value;
                if (ir) decisions.inventorRes = ir.value;
                if (rp) decisions.ramp = parseInt(rp.value, 10);
                if (!Number.isFinite(decisions.ramp) || decisions.ramp < 0 || decisions.ramp > 100) {
                    warn(`warn_ramp_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let commDelta = 0, identityDelta = 0, trustDelta = 0, revenueDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the identity tension and the portfolio (Common Errors 1 & 2: picking a pole).
                switch (d.stance) {
                    case `reconcile`: identityDelta += 12; trustDelta += 5; coachKey = `coach_r1_reconcile`; break;
                    case `commercial`: identityDelta -= 4; trustDelta -= 8; commDelta += 6; coachKey = `coach_r1_commercial`; break;
                    case `academic`: identityDelta += 2; trustDelta += 8; commDelta -= 8; coachKey = `coach_r1_academic`; break;
                    case `reporting`: identityDelta -= 10; trustDelta -= 6; commDelta += 4; coachKey = `coach_r1_reporting`; break;
                }

                // Portfolio priority — a balanced pair reads the tension correctly.
                switch (d.priority) {
                    case `balanced`: identityDelta += 8; commDelta += 4; if (d.stance === `reconcile`) coachKey = `coach_r1_sharp`; break;
                    case `deeptech`: identityDelta += 4; commDelta -= 6; trustDelta += 4; break;
                    case `software`: commDelta += 6; identityDelta -= 6; trustDelta -= 6; coachKey = `coach_r1_software`; break;
                    case `device`: commDelta += 6; identityDelta -= 8; trustDelta -= 4; coachKey = `coach_r1_device`; break;
                }

                // Engaging the faculty inventor early protects the highest-impact case (Common Error 4).
                if (d.inventor >= 60) { trustDelta += 8; identityDelta += 4; }
                else if (d.inventor <= 25) { trustDelta -= 8; coachKey = `coach_r1_inventor`; }

                summaryKey = (d.stance === `reconcile` && d.priority === `balanced`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose partnership models (Common Error 3: ceding control for cash).
                // Medical device — the strategic-investor exclusivity-plus-board-seat trap.
                switch (d.deviceModel) {
                    case `exclusive`: revenueDelta += 1.6; commDelta += 14; trustDelta -= 12; identityDelta -= 12; ds.cededControl = true; coachKey = `coach_r2_exclusive`; break;
                    case `negotiated`: revenueDelta += 1.1; commDelta += 12; identityDelta += 6; trustDelta += 2; coachKey = `coach_r2_negotiated`; break;
                    case `nonexclusive`: revenueDelta += 0.4; commDelta += 6; identityDelta += 6; trustDelta += 4; coachKey = `coach_r2_nonexcl`; break;
                    case `pass`: identityDelta += 2; trustDelta += 2; coachKey = `coach_r2_devicepass`; break;
                }

                // Deep-tech clean energy — flagship public-good invention.
                switch (d.deeptechModel) {
                    case `spinout`: commDelta += 10; identityDelta += 8; revenueDelta += 0.6; trustDelta += 4; break;
                    case `collaboration`: identityDelta += 10; trustDelta += 8; commDelta += 4; break;
                    case `exclusive`: revenueDelta += 1.0; commDelta += 8; identityDelta -= 10; trustDelta -= 8; coachKey = `coach_r2_dtexcl`; break;
                    case `pass`: commDelta -= 4; identityDelta -= 4; coachKey = `coach_r2_dtpass`; break;
                }

                // Fast B2B software — the “easy money” optics test.
                switch (d.softwareModel) {
                    case `nonexclusive`: revenueDelta += 0.8; commDelta += 10; identityDelta += 2; break;
                    case `exclusive`: revenueDelta += 1.2; commDelta += 12; trustDelta -= 6; identityDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r2_swexcl` : coachKey; break;
                    case `spinout`: commDelta += 6; identityDelta += 4; trustDelta += 2; break;
                    case `pass`: commDelta -= 2; break;
                }

                // Model coherence: a credible-fit mix reconciles rather than inflames the tension.
                const fitMix = (d.deviceModel === `negotiated` || d.deviceModel === `nonexclusive`) &&
                               (d.deeptechModel === `collaboration` || d.deeptechModel === `spinout`) &&
                               (d.softwareModel === `nonexclusive` || d.softwareModel === `spinout`);
                if (fitMix) { identityDelta += 8; trustDelta += 4; coachKey = `coach_r2_coherent`; }

                summaryKey = fitMix ? `sum_r2_good` :
                             (d.deviceModel === `exclusive` ? `sum_r2_ceded` : `sum_r2_weak`);
            } else if (round === 3) {
                // Allocate ₹9 cr across four inventions (Common Error 5: budget denial / spreading thin).
                const dt = d.deeptechSpend, dv = d.deviceSpend, sw = d.softwareSpend, pl = d.pipelineSpend;
                spend = Math.round((dt + dv + sw + pl) * 10) / 10;

                // Count how many inventions reach a credible funding threshold (proof of concept).
                const dtFunded = dt >= 3.5;             // partial-but-credible on the ₹7 cr deep-tech
                const dvFunded = dv >= 1.5;             // unlocks the strategic co-funding
                const swFunded = sw >= this.SOFTWARE_NEED;
                const backedCount = [dtFunded, dvFunded, swFunded].filter(Boolean).length;

                if (swFunded) { commDelta += 10; revenueDelta += 0.9; }
                if (dvFunded) { commDelta += 12; revenueDelta += 1.2; }
                if (dtFunded) { commDelta += 8; identityDelta += 8; revenueDelta += 0.4; }
                if (pl >= 2.0) { commDelta += 6; trustDelta += 8; identityDelta += 4; }  // pipeline = future disclosures
                else if (pl <= 0.5) { trustDelta -= 6; commDelta -= 4; }

                // Spreading thin: many tiny stakes, nothing reaches proof of concept.
                const spreadThin = backedCount === 0 && pl < 2.0;
                if (spreadThin) { ds.overCommitted = true; commDelta -= 12; identityDelta -= 6; coachKey = `coach_r3_spread`; }
                else if (backedCount >= 2 && pl >= 2.0) { coachKey = `coach_r3_focused`; }
                else if (coachKey === `coach_default`) { coachKey = `coach_r3_partial`; }

                // Resolve the anchor-licence renegotiation.
                switch (d.anchor) {
                    case `rebalance`: revenueDelta += 0.4; identityDelta += 6; trustDelta += 2; commDelta += 4; coachKey = `coach_r3_rebalance`; break;
                    case `hold`: revenueDelta -= 1.6; commDelta -= 2; coachKey = `coach_r3_hold`; break;   // licensee likely walks
                    case `concede`: revenueDelta -= 0.6; identityDelta -= 2; break;                        // weaker deal, dependency stays
                    case `replace`: revenueDelta -= 1.2; commDelta += 6; identityDelta += 4; coachKey = `coach_r3_replace`; break; // gap year risk
                }

                summaryKey = (backedCount >= 2 && pl >= 2.0 && d.anchor === `rebalance`) ? `sum_r3_good` :
                             (spreadThin ? `sum_r3_spread` : `sum_r3_weak`);
            } else if (round === 4) {
                // Integrate into one identity & an 18-month plan; defend it (Common Error 6: optimise one KPI).
                switch (d.identityStance) {
                    case `hybrid`: identityDelta += 14; trustDelta += 8; commDelta += 6; coachKey = `coach_r4_hybrid`; break;
                    case `commercial`: identityDelta -= 8; trustDelta -= 10; commDelta += 6; coachKey = `coach_r4_commercial`; break;
                    case `academic`: identityDelta += 2; trustDelta += 8; commDelta -= 10; coachKey = `coach_r4_academic`; break;
                    case `ambiguous`: identityDelta -= 12; trustDelta -= 6; coachKey = `coach_r4_ambiguous`; break;
                }

                // Final resolution of the faculty inventor's publish-and-abandon threat.
                switch (d.inventorRes) {
                    case `coauthor`: trustDelta += 14; identityDelta += 8; commDelta += 8; revenueDelta += 0.6; coachKey = (d.identityStance === `hybrid`) ? `coach_r4_aligned` : coachKey; break;
                    case `pressure`: trustDelta -= 10; identityDelta -= 6; if (d.inventor < 50) { ds.inventorLost = true; commDelta -= 14; revenueDelta -= 1.0; coachKey = `coach_r4_lost`; } break;
                    case `ignore`: ds.inventorLost = true; trustDelta -= 12; commDelta -= 16; revenueDelta -= 1.2; identityDelta -= 4; coachKey = `coach_r4_lost`; break;
                    case `release`: identityDelta += 4; trustDelta += 6; commDelta -= 12; revenueDelta -= 0.8; coachKey = `coach_r4_release`; break;
                }

                // Commit a commercialization ramp matched to what was actually funded.
                const funded = ds.comm;  // current standing reflects what the portfolio can deliver
                const overReach = d.ramp >= 75 && funded < 200;
                const underReach = d.ramp <= 25;
                if (overReach) { commDelta -= 8; trustDelta -= 4; identityDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_overreach` : coachKey; }
                else if (underReach) { commDelta -= 6; identityDelta -= 2; }
                else { commDelta += 8; identityDelta += 4; }

                summaryKey = (d.identityStance === `hybrid` && d.inventorRes === `coauthor`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: cumulative ₹ crore committed against the ₹9 cr cap.
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 10) / 10;

            // Apply deltas. Commercialization index is unbounded upward (baseline 100, target ~300);
            // identity & trust are 0–100; revenue is ₹ crore/yr and can dip below the anchor base.
            ds.comm = Math.max(0, Math.round(ds.comm + commDelta));
            ds.identity = Math.max(0, Math.min(100, Math.round(ds.identity + identityDelta)));
            ds.trust = Math.max(0, Math.min(100, Math.round(ds.trust + trustDelta)));
            ds.revenue = Math.max(0, Math.round((ds.revenue + revenueDelta) * 10) / 10);

            ds.commHistory.push(ds.comm);
            ds.identityHistory.push(ds.identity);
            ds.trustHistory.push(ds.trust);
            ds.revenueHistory.push(ds.revenue);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            // v1.1.0 — persist the composite where the gradebook actually reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            return {
                period: state.currentPeriod,
                comm: ds.comm,
                commDelta: Math.round(commDelta),
                identity: ds.identity,
                identityDelta: Math.round(identityDelta),
                trust: ds.trust,
                trustDelta: Math.round(trustDelta),
                revenue: ds.revenue,
                revenueDelta: Math.round(revenueDelta * 10) / 10,
                budgetUsed: ds.budgetUsed,
                cededControl: ds.cededControl,
                inventorLost: ds.inventorLost,
                overCommitted: ds.overCommitted,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: _score,
                overallScore: _score
            };
        }

        _fmtCrore(v) {
            // Locale-aware INR crore: English "₹2.2 cr/yr", Spanish "2,2 cr ₹/año".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(1).replace(`.`, `,`)} cr ₹/año`;
            }
            return `${sign}₹${abs.toFixed(1)} cr/yr`;
        }

        _fmtBudget(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${abs.toFixed(1).replace(`.`, `,`)} cr ₹`;
            }
            return `₹${abs.toFixed(1)} cr`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`commDisplay`, `domainState.comm`, (v) => {
                const card = document.querySelector(`.ortsim-card-comm`);
                if (card) {
                    card.classList.toggle(`ortsim-comm-strong`, Number(v) >= self.COMM_TARGET);
                    card.classList.toggle(`ortsim-comm-weak`, Number(v) <= 110);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`identityDisplay`, `domainState.identity`, (v) => Math.round(Number(v)));
            uiManager.bind(`trustDisplay`, `domainState.trust`, (v) => {
                const card = document.querySelector(`.ortsim-card-trust`);
                if (card) {
                    card.classList.toggle(`ortsim-trust-low`, Number(v) <= 30);
                    card.classList.toggle(`ortsim-trust-high`, Number(v) >= 70);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`revenueDisplay`, `domainState.revenue`, (v) => self._fmtCrore(Number(v)));
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.ortsim-budget-bar`);
                if (card) card.classList.toggle(`ortsim-budget-over`, Number(v) > self.BUDGET + 0.001);
                return self._fmtBudget(Number(v)) + ` / ` + self._fmtBudget(self.BUDGET);
            });

            // Inventor-engagement slider readout.
            const iv = document.getElementById(`inventorInput`);
            const ivReadout = document.getElementById(`inventorReadout`);
            if (iv && ivReadout) {
                ivReadout.textContent = iv.value;
                iv.addEventListener(`input`, function() { ivReadout.textContent = iv.value; });
            }

            // Ramp slider readout.
            const rp = document.getElementById(`rampInput`);
            const rpReadout = document.getElementById(`rampReadout`);
            if (rp && rpReadout) {
                rpReadout.textContent = rp.value;
                rp.addEventListener(`input`, function() { rpReadout.textContent = rp.value; });
            }

            // Budget live total (must hit ₹9 cr).
            const allocIds = [`deeptechSpend`, `deviceSpend`, `softwareSpend`, `pipelineSpend`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = total.toFixed(1);
                const bar = document.querySelector(`.ortsim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.BUDGET) > 0.001) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

