        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.identityHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                ortChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.identityHistory },
