        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const comm = Math.round(ds.comm);
            const identity = Math.round(ds.identity);
            const trust = Math.round(ds.trust);
            const revenue = ds.revenue;
            const commScore = Math.max(0, Math.min(100, ((comm - this.COMM_BASELINE) / (this.COMM_TARGET - this.COMM_BASELINE)) * 100));
            const revScore = Math.max(0, Math.min(100, (revenue / 6) * 100));
            return Math.round(commScore * 0.30 + identity * 0.28 + trust * 0.28 + revScore * 0.14);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const comm = Math.round(ds.comm);
            const identity = Math.round(ds.identity);
            const trust = Math.round(ds.trust);
            const revenue = ds.revenue;

            // Composite extracted to _composite() so the persisted per-period score and this
            // completion summary are identical by construction (v1.1.0).
            const composite = this._composite(ds);

            // v1.1.0 — the 3x mandate (comm >= COMM_TARGET = 300) is INFEASIBLE on the ₹9cr budget
            // (₹16cr combined need → comm ceiling ~204), which left the two success tiers UNREACHABLE.
            // Recalibrated to the fundable "strong commercialization" bar (~1.8x). Composite SCORE is
            // unchanged (commScore still normalises on COMM_TARGET); only the displayed tier label moves.
            const hitMandate = comm >= 180;
            const reconciled = identity >= 60 && trust >= 55;
            const facultyRevolt = trust <= 30 || ds.inventorLost;
            const soldOut = ds.cededControl && trust < 45;
            const restructured = comm < 180 && composite < 50;

            // v1.1.0 — tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_unresolved`;
            if (hitMandate && reconciled && composite >= 75) tierKey = `grade_reconciled`;
            else if (reconciled && comm >= 150) tierKey = `grade_mandatekept`;
            else if (facultyRevolt) tierKey = `grade_revolt`;
            else if (soldOut) tierKey = `grade_soldout`;
            else if (restructured) tierKey = `grade_restructured`;
            else if (composite >= 55) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (hitMandate && reconciled) insights.push(window.mySimulation.t(`insight_reconciled`));
            else if (facultyRevolt) insights.push(window.mySimulation.t(`insight_revolt`));
            else if (restructured) insights.push(window.mySimulation.t(`insight_restructured`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.cededControl) insights.push(window.mySimulation.t(`insight_ceded`));
            if (ds.inventorLost) insights.push(window.mySimulation.t(`insight_inventor`));
            if (ds.overCommitted) insights.push(window.mySimulation.t(`insight_spread`));
            if (comm < 180) insights.push(window.mySimulation.t(`insight_mandate_missed`));
            else if (comm >= 180) insights.push(window.mySimulation.t(`insight_mandate_hit`));
            if (identity >= 65 && trust >= 65) insights.push(window.mySimulation.t(`insight_trusted`));

            return {
                comm: comm,
                identity: identity,
                trust: trust,
                revenue: revenue,
                hitMandate: hitMandate,
                reconciled: reconciled,
                facultyRevolt: facultyRevolt,
                soldOut: soldOut,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="ort-cm"><p class="ort-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="ort-cm-chip ` + (ok ? `ort-cm-ok` : `ort-cm-no`) + `">` +
                `<span class="ort-cm-ico">` + (ok ? `\u2713` : `\u2717`) + `</span>` + label + ` \u00b7 ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="ort-cm-kpi"><div class="ort-cm-kpi-val">` + val +
                `</div><div class="ort-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="ort-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="ort-cm">` +
  `<div class="ort-cm-head">` +
    `<div class="ort-cm-score"><div class="ort-cm-score-num">` + Math.round(s.composite) +
       `<span class="ort-cm-score-den">/100</span></div>` +
       `<div class="ort-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="ort-cm-verdict"><div class="ort-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="ort-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="ort-cm-section"><div class="ort-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="ort-cm-chips">` + chip(!!s.hitMandate, t(`cm_t_mandate`)) + chip(!!s.reconciled, t(`cm_t_reconciled`)) +
      chip(!s.facultyRevolt, t(`cm_t_faculty`)) + chip(!s.soldOut, t(`cm_t_control`)) + `</div></div>` +
  `<div class="ort-cm-section"><div class="ort-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="ort-cm-kpis">` +
      kpi(t(`comm_label`), Math.round(s.comm), t(`cm_sub_comm`)) +
      kpi(t(`identity_label`), Math.round(s.identity), t(`cm_sub_identity`)) +
      kpi(t(`trust_label`), Math.round(s.trust), t(`cm_sub_trust`)) +
      kpi(t(`revenue_label`), this._fmtCrore(Number(s.revenue)), t(`cm_sub_revenue`)) +
    `</div></div>` +
  (insights ? `<div class="ort-cm-section"><div class="ort-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="ort-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.inventorLost) return window.mySimulation.t(`hint_inventor`);
            if (ds.overCommitted) return window.mySimulation.t(`hint_spread`);
            if (ds.cededControl && ds.trust < 45) return window.mySimulation.t(`hint_ceded`);
            if (ds.trust <= 30) return window.mySimulation.t(`hint_trust`);
            if (state.currentPeriod >= 3 && ds.comm < 160) return window.mySimulation.t(`hint_mandate`);
            if (ds.identity <= 30) return window.mySimulation.t(`hint_identity`);
            if (ds.comm >= this.COMM_TARGET && ds.identity >= 60 && ds.trust >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

