                { key: `results.trust`, label: `Trust`, i18nKey: `col_trust`, formatter: (v) => Math.round(v) },
                { key: `results.revenue`, label: `Revenue`, i18nKey: `col_revenue`, formatter: (v) => self._fmtCrore(Number(v)) }
            ];
