        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    title:                  `Identity at the Crossroads`,
                    subtitle:               `You direct a university tech-transfer office whose anchor licence is at risk and whose Dean demands a 3x commercialization jump on a flat ₹9 crore budget. Four inventions land at once and need ₹16 crore combined — but every funding choice signals what this office is. Reconcile the academic and commercial identities, pick the partnership models, and back the right portfolio.`,
                    header_tag:             `15 May 2026 · Office of Research Translation · Pragati Institute of Technology, Pune`,
                    round_label:            `Round`,
                    period_of:              `of`,
                    decisions_heading:      `Your Decisions This Round`,
                    submit_btn:             `Commit the Decision`,
                    undo_btn:               `Undo Last Round`,
                    history_heading:        `Round-by-Round Record`,
                    chart_heading:          `Commercialization, Identity & Trust Trajectory`,
                    chart_start:            `Start`,
                    coach_header:           `Facilitator (the Dean, the faculty senate & the strategic investor)`,
                    coach_intro:            `Three voices will judge you. The Dean wants a 3x commercialization jump in 18 months on a flat ₹9 crore. The faculty senate wants to know the office still serves the mission — and your pipeline is their goodwill. The strategic investor wants an exclusive licence and a board seat over a publicly funded invention. Every rupee you commit is an identity claim. Don't optimise one KPI in one room while the other three crater in another.`,

                    comm_label:             `Commercialization Index`,
                    comm_sub:               `Outcomes vs baseline · Dean wants ~300 (3x)`,
                    identity_label:         `Identity Coherence`,
                    identity_sub:           `Reconciled academic + commercial self (0–100)`,
                    trust_label:            `Faculty Trust`,
                    trust_sub:              `Disclosure & cooperation goodwill (0–100)`,
                    revenue_label:          `Revenue`,
                    revenue_sub:            `Projected running royalty · anchor ≈ ₹2.2 cr/yr`,
                    budget_label:           `Budget committed across the portfolio`,

                    clock_r1:               `18-month Dean review · clock running`,
                    clock_r2:               `Term sheets on the desk · board seat in play`,
                    clock_r3:               `₹9 cr to deploy · anchor renegotiation live`,
                    clock_r4:               `Defend the plan · Dean, senate, investor`,

                    round_name_r1:          `Diagnose`,
                    round_name_r2:          `Partnership Models`,
                    round_name_r3:          `Fund the Portfolio`,
                    round_name_r4:          `Reconcile & Defend`,

                    briefing_title_r1:      `Round 1 — Diagnose the identity tension and the portfolio`,
                    briefing_text_r1:       `Four invention dossiers, the anchor-licence terms, a flat ₹9 crore budget, and an identity fault line all land on your desk at once. The office holds <strong>two partly incompatible identities</strong> — academic steward (open inquiry, public good, publication) and commercial engine (revenue, spin-outs, exclusivity). Every funding choice is an <em>identity claim</em>, not just an NPV. Map the portfolio by time-to-revenue and risk, name where each choice pulls the office toward one pole or the other, and decide how early to engage the faculty inventor who has threatened to <strong>publish-and-abandon</strong> the highest-impact patent.`,
                    briefing_title_r2:      `Round 2 — Choose the partnership model for each invention`,
                    briefing_text_r2:       `For the inventions you intend to back, pick a model: <strong>exclusive licence</strong> (high cash, low control), <strong>non-exclusive</strong> (broad access, strong academic fit, lower revenue), <strong>spin-out</strong> (highest upside and burden), or <strong>sponsored/open-innovation collaboration</strong> (preserves publication, modest revenue). The strategic investor's medical-device offer of ₹5 crore demands an <em>exclusive global licence and a board seat</em> over a publicly funded invention — cash you need, control you may not want to cede. Match each model to revenue, control, speed, and identity coherence.`,
                    briefing_title_r3:      `Round 3 — Decide what to scale under the ₹9 crore budget`,
                    briefing_text_r3:       `The four inventions need ₹16 crore combined; you have ₹9 crore — <strong>only two can be fully backed</strong>. Trade the deep-tech long shot (₹7 cr, 4–5 yrs, best identity fit) against the fast software win (₹1.5 cr, 6 months, identity concern) against the strategic-investor device deal, and fund the pipeline so faculty keep disclosing. Half-fund all four and <em>none reaches proof of concept</em>. Then resolve the anchor-licence renegotiation — the ~₹2.2 cr/yr that is 80% of cumulative revenue is on the table — without gutting the operating base.`,
                    briefing_title_r4:      `Round 4 — Reconcile the identity and defend the 18-month plan`,
                    briefing_text_r4:       `Integrate the portfolio, the models and the identity stance into one recommendation, and defend it to the Dean, a faculty-senate representative, and the strategic investor. State what the ORT <strong>is</strong> — academic steward, commercial engine, or a reconciled hybrid. Close out the faculty inventor before she hits submit, and commit a commercialization ramp the funded portfolio can actually deliver: <em>over-promise and the review still fails; under-commit and you miss the mandate.</em> The Dean scores all four KPIs at once.`,

                    r1_stance_label:        `How do you frame the office's purpose to the team and the Dean?`,
                    r1_priority_label:      `Which invention best fits the office's reconciled identity AND the Dean's mandate?`,
                    r1_inventor_label:      `How early do you engage the faculty inventor threatening to publish-and-abandon? (%)`,
                    r1_inventor_readout:    `Effort to keep the inventor aligned:`,
                    stance_reconcile:       `A reconciled hybrid — manage the academic-vs-commercial tension rather than pick a side; funding choices are identity claims, not just NPV`,
                    stance_commercial:      `A commercial engine — revenue, spin-outs and exclusivity are how we survive the Dean's mandate; faculty will adapt`,
                    stance_academic:        `An academic steward — open inquiry and public good come first; commercialization must never compromise the mission`,
                    stance_reporting:       `A metrics exercise — just hit the 3x number any way we can and report it; identity is a soft distraction`,
                    priority_balanced:      `A balanced pair — one credible long-horizon bet plus a near-term win that funds the pipeline, sequenced by time-to-revenue and risk`,
                    priority_deeptech:      `The deep-tech clean-energy play only — biggest payoff, best public-good fit, ₹7 cr over 4–5 years`,
                    priority_software:      `The fast B2B software licence only — ₹1.5 cr, revenue in 6 months, hit the number fastest`,
                    priority_device:        `The strategic-investor device deal only — ₹5 cr cash now, take the board seat, worry about control later`,

                    r2_device_label:        `Partnership model for the medical device (strategic investor offering ₹5 cr).`,
                    r2_deeptech_label:      `Partnership model for the deep-tech clean-energy invention.`,
                    r2_software_label:      `Partnership model for the fast B2B software tool.`,
                    dm_exclusive:           `Exclusive global licence + board seat — take the ₹5 cr; accept investor influence over research direction`,
                    dm_negotiated:          `Negotiated exclusive — field-of-use limits, milestone clawback, an observer seat not a voting one; less cash, kept control`,
                    dm_nonexclusive:        `Non-exclusive licence — broad access, lower cash, strong academic fit, but the strategic investor likely walks`,
                    dm_pass:                `Pass on the device for now — protect control, forgo the cash`,
                    dtm_spinout:            `University spin-out — highest upside and control, highest funding and management burden, slow`,
                    dtm_collaboration:      `Sponsored-research / open-innovation collaboration — preserves publication and public-good identity, modest revenue`,
                    dtm_exclusive:          `Exclusive licence to an energy major — fastest cash, but cedes a flagship public-good invention to a private firm`,
                    dtm_pass:               `Pass — too slow and costly for an 18-month review`,
                    swm_nonexclusive:       `Non-exclusive licence — quick revenue with broad access; softens the “chasing easy money” critique`,
                    swm_exclusive:          `Exclusive licence — maximum near-term cash, sharper faculty concern about commercial drift`,
                    swm_spinout:            `Student/faculty spin-out — builds capability, slower than a licence, more management burden`,
                    swm_pass:               `Pass — avoid the “easy money” optics entirely`,

                    r3_alloc_label:         `Allocate the ₹9 crore budget across the four inventions (must total ₹9 cr)`,
                    r3_total_readout:       `Budget allocated:`,
                    r3_total_cap:           `/ ₹9.0 cr`,
                    r3_anchor_label:        `Resolve the anchor-licence renegotiation (licensee threatens to walk over royalty terms).`,
                    alloc_deeptech:         `Deep-tech clean energy — full need ₹7 cr · 4–5 yrs · best identity fit, biggest payoff`,
                    alloc_device:           `Medical device — strategic-investor co-funded, your share to unlock the ₹5 cr`,
                    alloc_software:         `Fast B2B software — full need ₹1.5 cr · revenue in 6 months`,
                    alloc_pipeline:         `Pipeline & IP prosecution — non-exclusive base + disclosure-to-filing for the other 236 inventions`,
                    anchor_hold:            `Hold firm on terms — defend the ~₹2.2 cr/yr, risk the licensee walking and gutting the operating base`,
                    anchor_concede:         `Concede a lower royalty to keep them — protect cash flow, accept a weaker deal and a one-hit dependency`,
                    anchor_rebalance:       `Rebalance — modest royalty concession plus new field-of-use sublicensing, and use the portfolio to reduce the 80% dependency`,
                    anchor_replace:         `Let it lapse and replace the revenue from the new portfolio — bold, but a gap year if the new deals slip`,

                    r4_identity_label:      `State the reconciled identity you defend to the Dean, the senate, and the investor.`,
                    r4_inventor_label:      `Final resolution of the faculty inventor's publish-and-abandon threat.`,
                    r4_ramp_label:          `How aggressively do you ramp the commercialization target you commit to the Dean? (%)`,
                    r4_ramp_readout:        `Committed commercialization ramp:`,
                    r4_ramp_hint:           `Over-promise a ramp your funded portfolio can't deliver and the 18-month review still fails — under-commit and you miss the mandate. Match the ramp to what you actually funded.`,
                    is_hybrid:              `A reconciled hybrid — an office that commercializes in service of the mission, transparent about the tension and how each model honours it`,
                    is_commercial:          `A commercial engine — defend the revenue and the deals; tell faculty the numbers are non-negotiable`,
                    is_academic:            `An academic steward — defend the mission; tell the Dean commercialization must wait for the right terms`,
                    is_ambiguous:           `Stay deliberately vague — give each stakeholder the version they want to hear`,
                    ir_coauthor:            `Co-design the deal — protect publication rights, co-authorship and a public-good clause so she licenses rather than publishes-and-abandons`,
                    ir_pressure:            `Pressure her — invoke the IP policy and insist she assigns the patent; fast, but she may submit anyway`,
                    ir_ignore:              `Build the plan around the invention regardless — assume she won't actually hit submit`,
                    ir_release:             `Let her publish — forfeit the patent value, honour the academic identity, lose the licensing case`,

                    warn_inventor_range:    `The inventor-engagement effort must be a percentage between 0 and 100.`,
                    warn_model_missing:     `Choose a partnership model for each invention before committing.`,
                    warn_alloc_negative:    `Budget allocations cannot be negative.`,
                    warn_alloc_total:       `The portfolio must total exactly ₹9 crore — the budget is a hard constraint. Re-balance.`,
                    warn_ramp_range:        `The commercialization ramp must be a percentage between 0 and 100.`,

                    coach_default:          `Decision logged.`,
                    coach_r1_reconcile:     `<strong>That's the right frame.</strong> The task is to <em>manage</em> the academic-vs-commercial tension, not eliminate it. Legitimacy with faculty depends on honouring the academic logic; legitimacy with me and with industry depends on delivering the market one. Treat every funding choice as an identity claim and your decisions can reinforce each other.`,
                    coach_r1_commercial:    `<strong>“Faculty will adapt” is the assumption that bankrupts the pipeline.</strong> Your pipeline is faculty goodwill — disclosures, follow-on inventions, the willingness to license rather than publish. Lead with revenue and exclusivity and the best work stops walking through your door. In 24 months your numbers stall because nobody brings you their inventions.`,
                    coach_r1_academic:      `<strong>You protected the office's soul — and may have signed its death warrant.</strong> Faculty will love you, but my 18-month review needs commercialization outcomes. Identity coherence that delivers commercial irrelevance is exactly the restructuring you feared. Mission and mandate both have to survive.`,
                    coach_r1_reporting:     `<strong>Treating this as a metrics exercise is Common Error number one.</strong> If you hit 3x by selling out the mission, the faculty senate hears the office has “sold out,” disclosures dry up, and the number you reported collapses the year after. Identity is not a soft distraction — it is your pipeline.`,
                    coach_r1_sharp:         `<strong>Sharp diagnosis.</strong> You framed the office as a reconciled hybrid <em>and</em> read the portfolio as a balanced pair — a credible long bet plus a near-term win that funds the pipeline. That is the institutional-theory move: hold both logics and sequence by time-to-revenue and risk.`,
                    coach_r1_software:      `<strong>Chasing only the quick software licence is the “easy money” signal.</strong> It hits the number fastest, but faculty read it as the office abandoning the hard, mission-fitting science. One fast win without a credible flagship tells everyone what you really value.`,
                    coach_r1_device:        `<strong>Leading with the strategic-investor device deal puts cash before control.</strong> ₹5 crore is tempting, but an exclusive licence and a board seat over a publicly funded invention is a governance question, not just a financing one. “Worry about control later” is how you end up not controlling your own research direction.`,
                    coach_r1_inventor:      `<strong>You're barely engaging the faculty inventor.</strong> She has threatened to publish-and-abandon the highest-impact patent. Identity reconciliation is operational, not rhetorical — if you don't bring her in before she hits submit, the licensing value you're planning around simply disappears.`,
                    coach_r2_exclusive:     `<strong>You granted an exclusive global licence and a board seat to a private investor over a publicly funded invention.</strong> The cash is real, but the faculty senate is asking who controls research direction now — and a journalist is asking the same. Did ₹5 crore buy you a partner or a governance crisis?`,
                    coach_r2_negotiated:    `<strong>A negotiated exclusive is the disciplined deal.</strong> Field-of-use limits, milestone clawbacks and an observer seat capture most of the cash while keeping control of research direction in the university. That's how you take strategic capital without ceding the institution's autonomy.`,
                    coach_r2_nonexcl:       `<strong>Non-exclusive on the device fits the mission</strong> — broad access, strong academic legitimacy — but the strategic investor was offering exclusivity for a reason, and they may well walk. You've protected identity; be honest with me about the revenue you've left on the table.`,
                    coach_r2_devicepass:    `<strong>Passing on the device protects control and forgoes the cash.</strong> Defensible — but with the anchor licence at risk, where does the running revenue come from? A clean conscience doesn't fund eleven staff.`,
                    coach_r2_dtexcl:        `<strong>An exclusive licence on the flagship clean-energy invention cedes a public-good asset to a private firm.</strong> Fastest cash, but it's the deep-tech play whose whole value to the office was its identity fit. You just converted your strongest mission asset into your sharpest legitimacy problem.`,
                    coach_r2_dtpass:        `<strong>Passing on the deep-tech play forfeits your best identity fit and biggest long-run payoff.</strong> It's slow for an 18-month review, true — but a sponsored-research collaboration would have kept it alive and kept faculty on side. Dropping it entirely is a signal too.`,
                    coach_r2_swexcl:        `<strong>An exclusive on the software maximises near-term cash but sharpens the “easy money” critique.</strong> A non-exclusive licence would have delivered quick revenue with broad access and far less faculty friction. Ask whether the extra cash is worth the trust it costs.`,
                    coach_r2_coherent:      `<strong>That's a coherent mix.</strong> A negotiated or non-exclusive device deal, a collaboration or spin-out on the deep-tech, and a broad-access software licence — each model matched to revenue, control and identity. The portfolio now tells one story instead of three contradictory ones.`,
                    coach_r3_focused:       `<strong>Focused and budget-honest.</strong> You backed two inventions to proof of concept and funded the pipeline instead of half-funding all four. That's the portfolio-triage discipline — under a hard constraint, two real bets beat four stranded ones.`,
                    coach_r3_partial:       `<strong>A partial spread is workable</strong> — but check that at least two inventions actually clear proof of concept and that the pipeline gets enough to keep faculty disclosing. Thin everywhere is the trap; deliberate priority is the skill.`,
                    coach_r3_spread:        `<strong>You committed across all four and none reached proof of concept.</strong> Half-funding everything against a ₹9 crore cap means four stranded projects and a starved pipeline. The CFO can't fund ₹16 crore of need — which two do you actually back, and what does passing on the others say about the office?`,
                    coach_r3_rebalance:     `<strong>Rebalancing the anchor licence is the mature move.</strong> A modest concession to keep the licensee, plus field-of-use sublicensing and a portfolio that dilutes the 80% dependency, protects cash <em>and</em> fixes the one-hit fragility. You're managing the renegotiation, not just surviving it.`,
                    coach_r3_hold:          `<strong>You held firm and the licensee walked.</strong> Defending the ~₹2.2 cr/yr on principle just removed 80% of cumulative revenue with nothing yet to replace it. Sometimes the strong negotiating position is the one that guts your operating base.`,
                    coach_r3_replace:       `<strong>Letting the anchor lapse to replace it from the new portfolio is bold.</strong> If the new deals land on time it resets the office's revenue base; if they slip, you've engineered a gap year right before the Dean's review. High conviction, real downside.`,
                    coach_r4_hybrid:        `<strong>A reconciled hybrid, defended honestly, is the durable identity.</strong> An office that commercializes in service of the mission — transparent about the tension and how each model honours it — is the answer to “who are we.” Faculty can live with it and I can score it.`,
                    coach_r4_commercial:    `<strong>Telling faculty the numbers are non-negotiable wins the quarter and loses the pipeline.</strong> You defended the revenue, but the senate now describes the office as a commercial shop bolted onto a university. That description is what stops the next disclosure.`,
                    coach_r4_academic:      `<strong>Defending the mission to me and asking commercialization to wait is brave — and it fails my review.</strong> “The right terms” is not an outcome I can take to the board. Identity coherence still has to produce commercialization, or the restructuring lands.`,
                    coach_r4_ambiguous:     `<strong>Telling each stakeholder what they want to hear is the fastest way to be trusted by none.</strong> The Dean, the senate and the investor talk to each other. A deliberately vague identity reads as no identity — and the contradictions surface the moment the three versions meet.`,
                    coach_r4_aligned:       `<strong>That's the integrated answer.</strong> A reconciled hybrid identity plus an inventor kept aligned through co-authorship and a public-good clause — you reconciled her academic identity with the office's commercial one <em>before</em> she hit submit. The plan holds across all three rooms.`,
                    coach_r4_lost:          `<strong>The inventor just submitted to a journal.</strong> The highest-impact patent is in the public domain — value gone. You can't commercialize what you didn't keep the inventor aligned on. Reconciliation was operational, and you treated it as rhetorical.`,
                    coach_r4_release:       `<strong>You let her publish.</strong> You honoured the academic identity and forfeited the patent value and the licensing case with it. A defensible identity claim — but the Dean's review still needs the outcomes the invention would have produced.`,
                    coach_r4_overreach:     `<strong>You committed a ramp your funded portfolio can't deliver.</strong> Promising the Dean a 3x outcome you didn't fund is over-promising into a review you'll still fail — and it costs you credibility now as well as later. Commit to what the portfolio can actually produce.`,

                    sum_default:            `Decision made.`,
                    sum_r1_good:            `Reconciled-hybrid framing; balanced portfolio read.`,
                    sum_r1_weak:            `Picked a pole or mis-read the portfolio.`,
                    sum_r2_good:            `Coherent model mix — control kept, identity intact.`,
                    sum_r2_ceded:           `Took the exclusive + board seat — control ceded.`,
                    sum_r2_weak:            `Model mix under-balanced on control or identity.`,
                    sum_r3_good:            `Two bets to proof of concept; anchor rebalanced.`,
                    sum_r3_spread:          `Spread thin — none reached proof of concept.`,
                    sum_r3_weak:            `Funding focus or anchor position under-resolved.`,
                    sum_r4_good:            `Reconciled identity; inventor kept aligned.`,
                    sum_r4_weak:            `Identity unresolved or inventor lost.`,

                    insight_reconciled:     `Reconciled hybrid: you hit the Dean's ~3x mandate while keeping identity coherence and faculty trust intact. You managed the academic-vs-commercial tension rather than picking a pole — credible models, a budget-honest portfolio, and an inventor kept aligned. This is the institutional-theory outcome: both logics held at once.`,
                    insight_revolt:         `Faculty revolt: trust collapsed or the inventor published-and-abandoned. The office may have hit a number, but its pipeline — faculty goodwill, disclosures, follow-on inventions — is gone. Commercial wins eroded the very trust the office depends on; the numbers fall the year after.`,
                    insight_restructured:   `Restructured: the 18-month review showed too few commercialization outcomes. Whether from academic purity or a portfolio that never reached proof of concept, the Dean's mandate went unmet and the restructuring you feared arrived.`,
                    insight_short:          `You didn't fully reconcile the four KPIs. Commercialization, identity, trust and revenue still pull in slightly different directions — enough for the Dean, the senate or the investor to find the seam.`,
                    insight_ceded:          `You ceded control: an exclusive licence and a board seat over a publicly funded invention bought cash but raised a governance and legitimacy question the faculty senate — and the press — are still asking.`,
                    insight_inventor:       `You lost the inventor: the highest-impact patent went to the public domain. Identity reconciliation is operational, not rhetorical — the licensing value you planned around evaporated the moment she hit submit.`,
                    insight_spread:         `You spread the budget too thin: committing across all four inventions against a ₹9 crore cap left none at proof of concept. Portfolio triage under a hard constraint means choosing — two real bets beat four stranded ones.`,
                    insight_mandate_hit:    `You hit the Dean's ~3x commercialization mandate — the survival condition for the office and the credibility you needed with the board.`,
                    insight_mandate_missed: `Commercialization stayed well below the Dean's 3x target. Legitimacy with the Dean and the board depends on outcomes; identity coherence alone does not satisfy the review.`,
                    insight_trusted:        `Identity coherence and faculty trust are both high — faculty would describe the office as a partner that commercializes in service of the mission. That trust is the pipeline that funds the next decade.`,

                    hint_inventor:          `You've lost the faculty inventor — the highest-impact patent is in the public domain. Next time, co-design the deal and protect publication before she hits submit.`,
                    hint_spread:            `Your budget is spread too thin — nothing reached proof of concept. Concentrate on two real bets and fund the pipeline; the ₹9 cr cap won't stretch to ₹16 cr of need.`,
                    hint_ceded:             `The exclusive licence and board seat ceded control of a public invention and faculty trust is suffering. A negotiated exclusive with field-of-use limits would have kept the cash and the control.`,
                    hint_trust:             `Faculty trust is dangerously low — your pipeline is their goodwill. Engage the inventor, choose mission-fitting models, and fund the disclosure pipeline before it dries up.`,
                    hint_mandate:           `Commercialization is well short of the Dean's 3x target with little time left. Back the near-term wins and the device deal to proof of concept, and commit a credible ramp.`,
                    hint_identity:          `Identity coherence has cratered — the office is reading as neither a credible academic steward nor a disciplined commercial engine. Frame a reconciled hybrid and match each model to it.`,
                    hint_strong:            `Strong position — mandate met, identity coherent, faculty trust healthy. Lock in the reconciled-hybrid story and keep the inventor aligned to hold it through the Dean's review.`,

